@startuml

class University {}

class Department {
  + name : string
}

class ResearchGroup {
  + name : string
  + groupID : int
}

class Researcher {
  + name : string
  + employeeID : int
  + email : string
}

class Project {
  + title : string
  + budget : float
  + startDate : date
}

class WorkPackage {
  + wpID : int
  + description : string
}

University "1" *-- "1..*" Department
Department "1" *-- "1..*" ResearchGroup
ResearchGroup "1" *-- "1..*" Researcher
ResearchGroup "1" *-- "1..*" WorkPackage : leads
Project "1" *-- "1..*" WorkPackage
WorkPackage "1..*" -- "0..*" Researcher : teamMember

@enduml

